return {
  json: {
    decision_id: $json.decision_id ?? null,
    telemetry_id: $json.telemetry_id ?? null,

    device_id: $json.device_id ?? null,
    room: $json.room ?? null,

    fan_action: $json.fan_action ?? "KEEP",
    light_action: $json.light_action ?? "KEEP",

    mode: $json.mode ?? null,
    decision_source: $json.decision_source ?? null,
    reason: $json.reason ?? null,

    timestamp: $json.timestamp ?? new Date().toISOString()
  }
};

const data = $input.first().json;

const commands = [];

// FAN command
if (['ON', 'OFF'].includes(data.fan_action)) {
  commands.push({
    json: {
      device_id: data.device_id,
      decision_id: data.decision_id,
      command_type: 'FAN',
      action: data.fan_action,
      source: 'AUTO',

      telemetry_id: data.telemetry_id,
      room: data.room,
      mode: data.mode,
      decision_source: data.decision_source,
      reason: data.reason
    }
  });
}

// LIGHT command
if (['ON', 'OFF'].includes(data.light_action)) {
  commands.push({
    json: {
      device_id: data.device_id,
      decision_id: data.decision_id,
      command_type: 'LIGHT',
      action: data.light_action,
      source: 'AUTO',

      telemetry_id: data.telemetry_id,
      room: data.room,
      mode: data.mode,
      decision_source: data.decision_source,
      reason: data.reason
    }
  });
}

return commands;

return {
  json: {
    command_id: $json.id,
    device_id: $json.deviceId,
    decision_id: $json.decisionId,

    command_type: $json.commandType,
    action: $json.action,

    source: $json.source,
    status: $json.status,

    payload: $json.payload,

    requested_at: $json.requestedAt
  }
};
